"""The G2-B verification contract: one enum, one registry, two generated packs, no drift.

The check registry (`contracts/verification/checks.v2.yaml`) is the source of truth for which
verification checks exist. Three things must not disagree with it:

* the `check_id` enum of `verification-request.v2` (the only free choice an operator has);
* the two deployment packs under `deploy/{lab,internet}/verify/`, generated by
  `scripts/verification_pack.py` (the internet pack is E1-only and has no Nuclei template);
* the template bytes the L1 check pins by sha256.

The tests also pin the shape the later slices build on: a result document carries what was seen
(never an expected value), and the read model refuses an impossible row (VERIFIED outside the lab,
VERIFIED without both negative controls, OBSERVED outside the internet).
"""

from __future__ import annotations

import importlib.util
import json
import re
import sys
from pathlib import Path
from typing import Any, cast

import pytest
import yaml

from aegis import validation
from aegis.common import verification
from aegis.common.repo import repository_root
from tests.support import load_fixture

REPO = repository_root()
SPEC = REPO / "contracts/verification"
LAB = REPO / "deploy/lab/verify"
INTERNET = REPO / "deploy/internet/verify"


def _schema(name: str) -> dict[str, Any]:
    return cast(dict[str, Any], json.loads((SPEC / name).read_text(encoding="utf-8")))


def _pack_module() -> Any:
    """scripts/verification_pack.py as a module (it is a script, not an importable package)."""
    path = REPO / "scripts/verification_pack.py"
    spec = importlib.util.spec_from_file_location("aegis_verification_pack_for_tests", path)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def test_the_request_enum_is_the_registry_in_review_order() -> None:
    request = _schema("verification-request.v2.schema.json")
    pack = verification.load_checks()
    assert request["properties"]["check_id"]["enum"] == list(pack.ids)


def test_a_check_id_is_a_contract_enum_not_a_free_form_parameter() -> None:
    request = _schema("verification-request.v2.schema.json")
    assert request["additionalProperties"] is False
    assert set(request["properties"]) == {"check_id", "expected_seq"}
    # Nothing that could reach a template, URL or argv element: no target, path, payload, method.
    for forbidden in ("target", "targets", "url", "path", "payload", "template", "headers"):
        assert forbidden not in request["properties"]


def test_every_registry_id_matches_the_run_and_result_patterns() -> None:
    pack = verification.load_checks()
    run = _schema("verification-run.v2.schema.json")
    result = _schema("verification-result.v2.schema.json")
    run_pattern = re.compile(run["properties"]["check_id"]["pattern"])
    result_pattern = re.compile(result["properties"]["check_id"]["pattern"])
    for check_id in pack.ids:
        assert run_pattern.fullmatch(check_id), check_id
        assert result_pattern.fullmatch(check_id), check_id


def test_the_committed_registry_has_one_lab_check_and_the_four_e1_checks() -> None:
    pack = verification.load_checks(LAB / "templates")
    assert [check.check_id for check in pack.lab_only()] == ["cve-2021-41773-traversal"]
    assert [check.check_id for check in pack.e1()] == [
        "config.tls.certificate",
        "config.tls.protocol",
        "config.http.version-header",
        "config.http.directory-listing",
    ]
    for check in pack.checks:
        assert check.targets.positive == 1, check.check_id
        assert check.targets.control_patched_twin == 1, check.check_id
        assert check.targets.control_benign == 1, check.check_id
        assert 1 <= check.per_target <= check.request_cap, check.check_id
        if check.lab_only:
            assert check.template is not None and check.template_sha256 is not None
            file = LAB / "templates" / check.template
            assert verification.template_sha256(file) == check.template_sha256
        else:
            assert check.template is None and check.template_sha256 is None


def test_no_check_rule_is_shared() -> None:
    pack = verification.load_checks()
    rules = [check.finding_rule for check in pack.checks]
    assert len(rules) == len(set(rules))


def test_the_generated_packs_are_current() -> None:
    assert _pack_module().check() == []


def test_the_internet_pack_is_e1_only_and_has_no_template() -> None:
    document = yaml.safe_load((INTERNET / "checks.v2.yaml").read_text(encoding="utf-8"))
    pack = verification.load_checks()
    assert [check["id"] for check in document["checks"]] == [check.check_id for check in pack.e1()]
    for check in document["checks"]:
        assert check["class"] == "E1"
        assert check["labOnly"] is False
        assert "template" not in check and "templateSha256" not in check
    files = sorted(path.name for path in INTERNET.rglob("*") if path.is_file())
    assert files == ["checks.v2.yaml"]
    assert not (INTERNET / "templates").exists()


def test_the_lab_pack_contains_exactly_the_declared_templates() -> None:
    pack = verification.load_checks(LAB / "templates")
    declared = {check.template for check in pack.checks if check.template is not None}
    on_disk = {
        path.name for path in (LAB / "templates").rglob("*") if path.is_file() or path.is_symlink()
    }
    assert on_disk == declared


def test_the_result_document_cannot_carry_an_expected_value() -> None:
    result = _schema("verification-result.v2.schema.json")
    assert result["additionalProperties"] is False
    assert "expected" not in result["properties"] and "canary" not in result["properties"]
    # The E1 oracles of M21 read these structured values from the stored result document.
    observed = result["$defs"]["Observation"]["properties"]
    assert {
        "expired",
        "self_signed",
        "not_after_epoch",
        "accepted_versions",
        "attempts",
        "server",
        "x_powered_by",
        "product",
        "version",
        "listing",
        "files",
        "negotiated_version",
    } <= set(observed)


def test_the_read_model_refuses_an_impossible_row() -> None:
    reference = "verification/verification-run.v2.schema.json"
    assert not validation.errors(reference, load_fixture("valid/verification-run.verified.json"))
    assert not validation.errors(reference, load_fixture("valid/verification-run.observed.json"))
    for fixture in (
        "invalid/verification-run.internet-verified.json",
        "invalid/verification-run.verified-without-controls.json",
        "invalid/verification-run.observed-in-lab.json",
    ):
        assert validation.errors(reference, load_fixture(fixture)), fixture


def test_pack_hash_is_sorted_and_content_addressed(tmp_path: Path) -> None:
    first = tmp_path / "first"
    second = tmp_path / "second"
    for directory, order in ((first, ("b.yaml", "a.yaml")), (second, ("a.yaml", "b.yaml"))):
        directory.mkdir()
        for name in order:
            (directory / name).write_text(name + "\n", encoding="utf-8")
    assert verification.pack_sha256(first) == verification.pack_sha256(second)

    (second / "a.yaml").write_text("changed\n", encoding="utf-8")
    assert verification.pack_sha256(first) != verification.pack_sha256(second)

    (first / "link.yaml").symlink_to(first / "a.yaml")
    with pytest.raises(ValueError, match="symlink"):
        verification.pack_sha256(first)
